def build(language, output):
    data=json.loads((ROOT/f'content.{language}.json').read_text(encoding='utf-8'))
    blocks={item['id']:item['spans'] for item in data['blocks']}
    c=canvas.Canvas(str(output),pagesize=A4,pageCompression=1)
    c.setTitle(data['meta']['title'])
    c.setAuthor('')
    for page_no in range(1,22):
        for row in FILLS[str(page_no)]:
            x0,y0,x1,y1,r,g,b=row
            c.setFillColorRGB(r,g,b)
            c.rect(x0,A4[1]-y1,x1-x0,y1-y0,stroke=0,fill=1)
        for block_id,positions in LAYOUT[str(page_no)]:
            spans=blocks[block_id]
            if not spans and language=='en':
                continue  # Translation must be completed before producing English release.
            if len(spans)!=len(positions):
                raise ValueError(f'{block_id}: span count differs from layout')
            for txt,(x,y,size,font,color) in zip(spans,positions):
                c.setFont('DejaVuSans-Bold' if 'Bold' in font else 'DejaVuSans',size)
                c.setFillColorRGB(((color>>16)&255)/255,((color>>8)&255)/255,(color&255)/255)
                c.drawString(x,A4[1]-y,txt)
        c.showPage()
    c.save()

if __name__=='__main__':
    SCRATCH.mkdir(exist_ok=True)
    build('de', SCRATCH/'Amazon-Geraete-Leitfaden-de-rebuild.pdf')
    if all(x['spans'] for x in json.loads((ROOT/'content.en.json').read_text(encoding='utf-8'))['blocks']):
        target=REPO/'downloads'/'Amazon-Devices-Guide-2026-10-22-neutral-en.pdf'
        target.parent.mkdir(exist_ok=True)
        build('en',target)
